    description: {
      de: "Die größte Stadt und Hauptstadt Libyens, malerisch an der Mittelmeerküste gelegen.",
      hu: "Líbia fővárosa és legnépesebb városa, amely a Földközi-tenger partján fekszik.",
      ro: "Capitala și cel mai populat oraș al Libiei, situat pe coasta Mării Mediterane.",
      en: "The capital and most populous city of Libya, located along the Mediterranean Sea."
    },
    facts: {
      de: ["Zentrum für Politik und Wirtschaft.", "Besitzt eine gut erhaltene historische Altstadt."],
      hu: ["A politikai és gazdasági élet központja.", "Jól megőrzött történelmi óvárossal (Medina) büszkélkedhet."],
      ro: ["Centrul politic și economic al țării.", "Se mândrește cu un oraș vechi (Medina) bine conservat."],
      en: ["The political and economic hub of the country.", "Boasts a well-preserved historic old town."]
    },
    descriptionAdvanced: {
      de: "Tripolis, das historische Oea, ist eine der ältesten Städte im Mittelmeerraum und blickt auf eine über 2.500-jährige Geschichte zurück. Das Herz der Stadt ist die Medina, ein Labyrinth aus engen Gassen, das von antiken Mauern geschützt wird und in dem traditionelle Souks eine Vielzahl von Waren anbieten. Innerhalb der Altstadt befindet sich die massive Festung Assaraya al-Hamra (Das Rote Schloss), die heute das Nationalmuseum beherbergt und Exponate von der phönizischen bis zur osmanischen Zeit zeigt. Ein weiteres bedeutendes Denkmal ist der Bogen des Mark Aurel, ein beeindruckendes Zeugnis der römischen Herrschaft. Außerhalb der Altstadtmauern ist das Stadtbild von italienischer Kolonialarchitektur aus dem frühen 20. Jahrhundert geprägt, insbesondere rund um den Platz der Märtyrer. Die Lage direkt am Mittelmeer verleiht der Stadt ein angenehmes Klima und eine belebte Uferpromenade, die am Abend ein beliebter Treffpunkt für die Bewohner ist.",
      hu: "Tripoli, az ókori Oea, a Földközi-tenger partvidékének egyik legrégebbi városa, amelyet még a föníciaiak alapítottak az i. e. 7. században. A város lelke a Medina, azaz az óváros, ahol szűk utcák és sikátorok labirintusában hagyományos piacok (szukok) kínálják portékáikat a fűszerektől a kézműves termékekig. Itt található a Vörös Kastély (Assaraya al-Hamra) impozáns erődítménye is, amely jelenleg a Nemzeti Múzeumnak ad otthont, bemutatva Líbia gazdag régészeti örökségét a római kortól az oszmán időkig. A római uralom egyik legszebb emléke Marcus Aurelius diadalíve, amely az óváros északi részén áll. Az óvároson kívül a városkép a 20. század eleji olasz gyarmati építészet stílusjegyeit viseli magán, különösen a Mártírok tere környékén. A tengerparti fekvés kellemes klímát biztosít, a parti sétány pedig a helyiek kedvelt közösségi helyszíne, különösen a naplemente idején.",
      ro: "Tripoli, cunoscut în antichitate sub numele de Oea, este unul dintre cele mai vechi orașe din bazinul mediteraneean, fiind fondat de fenicieni în secolul al VII-lea î.Hr. Inima orașului este Medina, un labirint de străduțe înguste protejate de ziduri vechi, unde piețele tradiționale (souq) oferă o varietate de produse, de la obiecte de artizanat la mirodenii. În cadrul Medinei se află Castelul Roșu (Assaraya al-Hamra), o fortăreață impunătoare care găzduiește Muzeul Național, unde sunt expuse vestigii din perioadele feniciană, romană și otomană. Un alt monument emblematic este Arcul lui Marcus Aurelius, o dovadă a prosperității orașului sub dominație romană. În afara zidurilor vechi, arhitectura orașului reflectă perioada colonială italiană de la începutul secolului XX, cu bulevarde largi și clădiri elegante. Situat pe malul mării, orașul beneficiază de o faleză animată, care este locul preferat de promenadă al localnicilor în timpul serii.",
      en: "Tripoli, historically known as Oea, is one of the oldest cities in the Mediterranean, founded by the Phoenicians in the 7th century BC. The heart of the city is the Medina, a labyrinth of narrow alleys protected by ancient walls, where traditional markets (souqs) offer everything from fine textiles to handmade jewelry. Within the old city lies the massive fortress of Assaraya al-Hamra (The Red Castle), which now houses the National Museum, showcasing Libya's diverse archaeological heritage from prehistoric times to the modern era. Another landmark is the Arch of Marcus Aurelius, a beautifully preserved remnant of the city's prosperous Roman era. Outside the historic walls, the architecture shifts to Italian colonial styles from the early 20th century, particularly around Martyrs' Square. The city's coastal location provides a Mediterranean climate, and the long promenade along the sea is a popular social hub for locals to gather and enjoy the ocean breeze in the evening."
    },
