      hu: ["Kr. e. 700 körül alapították.", "A líbiai kormány székhelye.", "Az ország legnépesebb városa.", "Itt található Líbia legnagyobb kikötője.", "A történelmi óváros neve Medina.", "Országos oktatási központ."],
