      ro: ["Este unul dintre cele mai importante noduri comerciale.", "Găzduiește una dintre cele mai mari zone de liber schimb."],
      en: ["One of the most important commercial hubs.", "Hosts one of the largest free trade zones in the region."],
      es: ["Se cuenta entre los centros comerciales más importantes.", "Cuenta con una de las mayores zonas de libre comercio."],
      pt: ["Conta-se entre os centros comerciais mais importantes.", "Possui uma das maiores zonas de comércio livre."],
