      ro: ["Principalul nod de transport din Sahara.", "Cunoscut pentru fortul său din deșert."],
      en: ["Major transport hub into the Sahara.", "Known for its distinctive desert fort."],
      es: ["Principal nudo de transporte hacia el Sáhara.", "Conocida por su fuerte del desierto."],
      pt: ["Principal nó de transportes para o Sara.", "Conhecida pela sua fortaleza do deserto."],
      fr: ["Principal carrefour de transport vers le Sahara.", "Connue pour son fort du désert."],
