      en: ["Surrounded by wheat fields.", "Provides a cooler retreat during summer."],
      es: ["Rodeada de campos de cereales.", "Ofrece un refugio más fresco en verano."],
      pt: ["Rodeada por campos de cereais.", "Oferece um refúgio mais fresco no Verão."],
