      en: ["Jaghbub was established in 1856 as the headquarters of the Senussi order.", "The oasis is located in a geological depression about 20 meters below sea level.", "It once housed one of the most prominent Islamic universities in Africa.", "The town is connected to Tobruk via a 300-kilometer desert highway.", "It is the burial place of the Grand Senussi, the founder of the movement.", "Date palm cultivation is the backbone of the local oasis economy."],
