      en: ["Known for traditional architecture.", "Important station on the mountain road."],
      es: ["Conocida por su arquitectura tradicional.", "Estación importante en la carretera de montaña."],
      pt: ["Conhecida pela sua arquitectura tradicional.", "Estação importante na estrada de montanha."],
